// Package codec provides shared little-endian binary encoding and decoding
// primitives used across the Go client library.
//
// The Reader and Writer types accumulate errors silently: once an error is
// recorded, all subsequent operations become no-ops that leave the accumulated
// error untouched. This lets callers issue a sequence of reads or writes and
// check for failure once at the end via Err.
package codec

import (
	"fmt"
	"runtime"
)

// caller returns the "file:line" location of the first frame on the stack that
// does not belong to this package's own source files. This points the error at
// the user's call site rather than at an internal helper, regardless of how
// many internal frames sit between the public method and the failure point.
func caller() string {
	for skip := 2; skip < 32; skip++ {
		_, file, line, ok := runtime.Caller(skip)
		if !ok {
			break
		}
		if !isCodecSource(file) {
			return fmt.Sprintf("%s:%d", file, line)
		}
	}
	return "unknown:0"
}

// isCodecSource reports whether file is one of this package's implementation
// files, whose frames should be skipped when locating the caller.
func isCodecSource(file string) bool {
	switch base(file) {
	case "codec.go", "reader.go", "writer.go":
		return true
	default:
		return false
	}
}

// base returns the final path element of file without importing path/filepath.
func base(file string) string {
	for i := len(file) - 1; i >= 0; i-- {
		if file[i] == '/' || file[i] == '\\' {
			return file[i+1:]
		}
	}
	return file
}
