package codec

import (
	"encoding"
	"encoding/binary"
	"fmt"
	"math"
)

// Reader is a binary deserializer that reads sequentially from a byte slice
// using little-endian encoding. It accumulates errors silently: once an error
// is set (for example, on buffer overrun), every subsequent read is a no-op
// that returns the zero value without overwriting the recorded error.
type Reader struct {
	buf []byte
	pos int
	err error
}

// NewReader returns a Reader that consumes payload from the beginning.
func NewReader(payload []byte) *Reader {
	return &Reader{buf: payload}
}

// ensure reports whether n bytes are available to read. If an error has already
// been recorded it returns false without touching it; on overrun it records an
// error tagged with the caller's location.
func (r *Reader) ensure(n int) bool {
	if r.err != nil {
		return false
	}
	if n < 0 || n > len(r.buf)-r.pos {
		r.err = fmt.Errorf("reader: need %d bytes, have %d (at %s)", n, len(r.buf)-r.pos, caller())
		return false
	}
	return true
}

// U8 reads a single byte as a uint8.
func (r *Reader) U8() uint8 {
	if !r.ensure(1) {
		return 0
	}
	v := r.buf[r.pos]
	r.pos++
	return v
}

// U16 reads 2 bytes as a little-endian uint16.
func (r *Reader) U16() uint16 {
	if !r.ensure(2) {
		return 0
	}
	v := binary.LittleEndian.Uint16(r.buf[r.pos:])
	r.pos += 2
	return v
}

// U32 reads 4 bytes as a little-endian uint32.
func (r *Reader) U32() uint32 {
	if !r.ensure(4) {
		return 0
	}
	v := binary.LittleEndian.Uint32(r.buf[r.pos:])
	r.pos += 4
	return v
}

// U64 reads 8 bytes as a little-endian uint64.
func (r *Reader) U64() uint64 {
	if !r.ensure(8) {
		return 0
	}
	v := binary.LittleEndian.Uint64(r.buf[r.pos:])
	r.pos += 8
	return v
}

// F32 reads 4 bytes as an IEEE 754 little-endian float32.
func (r *Reader) F32() float32 {
	if !r.ensure(4) {
		return 0
	}
	v := math.Float32frombits(binary.LittleEndian.Uint32(r.buf[r.pos:]))
	r.pos += 4
	return v
}

// Str reads exactly n bytes and returns them as a string, with no length prefix.
func (r *Reader) Str(n int) string {
	if !r.ensure(n) {
		return ""
	}
	s := string(r.buf[r.pos : r.pos+n])
	r.pos += n
	return s
}

// U32LenStr reads a 4-byte little-endian uint32 length prefix followed by that
// many bytes as a string.
func (r *Reader) U32LenStr() string {
	n := r.U32()
	return r.Str(int(n))
}

// U8LenStr reads a 1-byte uint8 length prefix followed by that many bytes as a
// string.
func (r *Reader) U8LenStr() string {
	n := r.U8()
	return r.Str(int(n))
}

// Raw reads exactly n bytes and returns them as a []byte.
func (r *Reader) Raw(n int) []byte {
	if !r.ensure(n) {
		return nil
	}
	b := r.buf[r.pos : r.pos+n]
	r.pos += n
	return b
}

// Obj reads n bytes and unmarshals them into v. If v.UnmarshalBinary returns an
// error, it is recorded on the Reader.
func (r *Reader) Obj(n int, v encoding.BinaryUnmarshaler) {
	if !r.ensure(n) {
		return
	}
	b := r.buf[r.pos : r.pos+n]
	r.pos += n
	if err := v.UnmarshalBinary(b); err != nil {
		r.err = err
	}
}

// Remaining returns the number of bytes not yet consumed from the buffer.
func (r *Reader) Remaining() int {
	return len(r.buf) - r.pos
}

// Err returns the accumulated error, or nil if none has occurred.
func (r *Reader) Err() error {
	return r.err
}
