package codec

import (
	"encoding"
	"encoding/binary"
	"fmt"
	"math"
)

// Writer is a binary serializer that appends sequentially to an internal byte
// slice using little-endian encoding. It accumulates errors silently: once an
// error is set, every subsequent write is a no-op that leaves the buffer and
// the recorded error unchanged.
type Writer struct {
	p   []byte
	err error
}

// NewWriter returns an empty Writer.
func NewWriter() *Writer {
	return &Writer{}
}

// NewWriterCap returns a Writer whose buffer is pre-allocated with capacity for
// at least n bytes, so that writes totaling n bytes do not force a reallocation.
func NewWriterCap(n int) *Writer {
	if n < 0 {
		n = 0
	}
	return &Writer{p: make([]byte, 0, n)}
}

// U8 appends a single byte.
func (w *Writer) U8(v uint8) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, v)
}

// U16 appends v as 2 little-endian bytes.
func (w *Writer) U16(v uint16) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint16(w.p, v)
}

// U32 appends v as 4 little-endian bytes.
func (w *Writer) U32(v uint32) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, v)
}

// U64 appends v as 8 little-endian bytes.
func (w *Writer) U64(v uint64) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint64(w.p, v)
}

// F32 appends v as 4 IEEE 754 little-endian bytes.
func (w *Writer) F32(v float32) {
	if w.err != nil {
		return
	}
	w.p = binary.LittleEndian.AppendUint32(w.p, math.Float32bits(v))
}

// Str appends the raw bytes of s with no length prefix.
func (w *Writer) Str(s string) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, s...)
}

// U32LenStr appends a 4-byte little-endian uint32 length prefix followed by the
// bytes of s.
func (w *Writer) U32LenStr(s string) {
	if w.err != nil {
		return
	}
	w.U32(uint32(len(s)))
	w.Str(s)
}

// U8LenStr appends a 1-byte uint8 length prefix followed by the bytes of s. If s
// is longer than 255 bytes it records an error tagged with the caller's
// location and leaves the buffer unchanged.
func (w *Writer) U8LenStr(s string) {
	if w.err != nil {
		return
	}
	if len(s) > 255 {
		w.err = fmt.Errorf("string length %d exceeds 255 (at %s)", len(s), caller())
		return
	}
	w.U8(uint8(len(s)))
	w.Str(s)
}

// Raw appends all bytes from b.
func (w *Writer) Raw(b []byte) {
	if w.err != nil {
		return
	}
	w.p = append(w.p, b...)
}

// Obj marshals v and appends the result. If v.MarshalBinary returns an error, it
// is recorded on the Writer, tagged with the caller's location, and the buffer
// is left unchanged.
func (w *Writer) Obj(v encoding.BinaryMarshaler) {
	if w.err != nil {
		return
	}
	b, err := v.MarshalBinary()
	if err != nil {
		w.err = fmt.Errorf("writer: marshal binary failed (at %s): %w", caller(), err)
		return
	}
	w.p = append(w.p, b...)
}

// Bytes returns the accumulated buffer. If an error has been recorded, it
// returns an empty slice instead.
func (w *Writer) Bytes() []byte {
	if w.err != nil {
		return []byte{}
	}
	return w.p
}

// Err returns the accumulated error, or nil if none has occurred.
func (w *Writer) Err() error {
	return w.err
}
